# -*- coding: utf-8 -*-
"""
BÀI SÁP NHẬP V4.5.2.2 - CHUẨN HÓA XEM TRƯỚC SÁP NHẬP PHÁT SINH

Mục tiêu nội bộ:
- Không đổi nghiệp vụ sáp nhập.
- Không thực hiện sáp nhập.
- Không chủ động ghi phocap.db.
- Chuẩn hóa nốt nội dung hiển thị ở luồng sáp nhập phát sinh:
  bỏ dấu vết số phiên bản, TARGET/SOURCE/PASS/BLOCK và từ "blocker" khỏi UI;
  đổi một số thuật ngữ kỹ thuật sang tiếng Việt dễ hiểu.
"""
from __future__ import annotations
import base64, datetime as dt, hashlib, json, os, py_compile, re, shutil, traceback
from pathlib import Path

TITLE = "BÀI SÁP NHẬP V4.5.2.2 - CHUẨN HÓA XEM TRƯỚC SÁP NHẬP PHÁT SINH"
EMBEDDED_FILES = {'app/templates/data_tools/school_merger_future_v45.html': '',
 'app/templates/data_tools/school_merger_future_preview_v45.html': '',
 'app/templates/data_tools/school_merger_future_result_v45.html': '',
 'app/services/school_merger_future_service.py': ''}
EXPECTED_BASE_HASHES = {'app/templates/data_tools/school_merger_future_v45.html': 'a99d32bca310279ed578a1e33c468dcc4451f38a55aaf4f7c7f1785ba5def901',
 'app/templates/data_tools/school_merger_future_preview_v45.html': '229c887e3cf0efb5244b7731fdd2c657f4eafa7fc71880614fc473930ed20a7b',
 'app/templates/data_tools/school_merger_future_result_v45.html': '839f86fa1459ebc847975e285ae75ca4d6462b4250879e9e5ec5031196ba6e06',
 'app/services/school_merger_future_service.py': '528a337f91f687d257ea4e2eaf1fd84395e472e025617b8a3ccab0dcd88963b3'}
FINAL_HASHES = {'app/templates/data_tools/school_merger_future_v45.html': '1639e50420e77d4169519b2f64b0be44e4b5ee2f061cfeb94abc817e8f5bd16a',
 'app/templates/data_tools/school_merger_future_preview_v45.html': '7e79059482946ba3005af49d3c900ca78990bfb623319e6c74f7957ab1b2f5ab',
 'app/templates/data_tools/school_merger_future_result_v45.html': 'a1fd7391a35f60227b3c67b2183a5c6b329a93977d6ff8c0e8eba1443d075b36',
 'app/services/school_merger_future_service.py': 'e4be6feb1e96911ecd90e4c33786821d4fb0c223e18f9553af39c3c104d86eac'}

def sha256_file(p: Path) -> str:
    h = hashlib.sha256()
    with p.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()

def db_fingerprint(db: Path) -> str:
    h = hashlib.sha256()
    for p in [db, Path(str(db)+"-wal"), Path(str(db)+"-shm")]:
        h.update(p.name.encode("utf-8"))
        if p.exists():
            h.update(str(p.stat().st_size).encode("ascii"))
            h.update(sha256_file(p).encode("ascii"))
        else:
            h.update(b"MISSING")
    return h.hexdigest()

def fail(msg: str):
    raise RuntimeError(msg)

def visible_ui_text(raw: str) -> str:
    raw = re.sub(r"<!--.*?-->", " ", raw, flags=re.S)
    raw = re.sub(r"\{#.*?#\}", " ", raw, flags=re.S)
    raw = re.sub(r"<script\b.*?</script>", " ", raw, flags=re.S | re.I)
    raw = re.sub(r"<style\b.*?</style>", " ", raw, flags=re.S | re.I)
    raw = re.sub(r"<[^>]+>", " ", raw, flags=re.S)
    raw = re.sub(r"\s+", " ", raw)
    return raw

def main():
    cwd = Path.cwd().resolve()
    script_dir = Path(__file__).resolve().parent
    root = cwd if (cwd / "app").exists() else script_dir
    if not (root / "app").exists():
        fail(r"Không tìm thấy thư mục app. Hãy chép bộ cài vào C:\PhoCap và chạy tại C:\PhoCap.")
    db = root / "data" / "phocap.db"
    if not db.exists():
        fail(f"Không tìm thấy database: {db}")

    ts = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_dir = root / "backups" / f"backup_truoc_chuan_hoa_xem_truoc_phat_sinh_{ts}"
    export_dir = root / "exports" / "Chuan_Hoa_Xem_Truoc_Sap_Nhap_Phat_Sinh"
    report_path = export_dir / f"bao_cao_{ts}.json"
    db_before = db_fingerprint(db)
    touched = []

    try:
        for rel in EMBEDDED_FILES:
            p = root / rel
            if not p.exists():
                fail(f"Thiếu tệp nền: {rel}")
            cur = sha256_file(p)
            if cur not in {EXPECTED_BASE_HASHES[rel], FINAL_HASHES[rel]}:
                fail(f"Tệp {rel} không đúng nền đã khóa. SHA hiện tại={cur}")

        backup_dir.mkdir(parents=True, exist_ok=True)
        for rel in EMBEDDED_FILES:
            src = root / rel
            dst = backup_dir / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)

        for rel, b64 in EMBEDDED_FILES.items():
            p = root / rel
            p.write_bytes(base64.b64decode(b64))
            touched.append(rel)

        for rel, expected_hash in FINAL_HASHES.items():
            got = sha256_file(root / rel)
            if got != expected_hash:
                fail(f"SHA sau cài không đúng: {rel}")

        py_compile.compile(str(root / "app/services/school_merger_future_service.py"), doraise=True)

        preview = (root / "app/templates/data_tools/school_merger_future_preview_v45.html").read_text(encoding="utf-8")
        future = (root / "app/templates/data_tools/school_merger_future_v45.html").read_text(encoding="utf-8")
        result = (root / "app/templates/data_tools/school_merger_future_result_v45.html").read_text(encoding="utf-8")
        visible = " ".join([visible_ui_text(preview), visible_ui_text(future), visible_ui_text(result)])

        version_re = re.compile(r"(?:Bài\s+)?V\d+(?:\.\d+)+", re.I)
        hits = sorted(set(m.group(0) for m in version_re.finditer(visible)))
        if hits:
            fail("Vẫn còn số phiên bản trong nội dung hiển thị: " + ", ".join(hits))

        required = [
            "ĐÍCH", "NGUỒN", "ĐẠT", "CHẶN",
            "DB đủ điều kiện kế thừa",
            "Hồ sơ đội ngũ kế thừa",
            "Hãy xử lý các lỗi cần xử lý phía trên.",
            "đã ngừng hoạt động/đã sáp nhập",
        ]
        for needle in required:
            if needle not in (preview + future + result):
                fail(f"Thiếu nội dung UI sau chuẩn hóa: {needle}")

        service = (root / "app/services/school_merger_future_service.py").read_text(encoding="utf-8")
        if "_normalize_source_audit_ui_message" not in service:
            fail("Thiếu bộ chuẩn hóa thông báo kiểm tra dữ liệu nguồn.")
        if '"Kiểm tra dữ liệu nguồn – "' not in service:
            fail("Thông báo kiểm tra dữ liệu nguồn chưa được chuẩn hóa.")

        db_after = db_fingerprint(db)
        if db_after != db_before:
            fail("Database/WAL đã thay đổi trong bộ cài. Đã dừng an toàn.")

        export_dir.mkdir(parents=True, exist_ok=True)
        report = {
            "installed_at": dt.datetime.now().isoformat(timespec="seconds"),
            "title_internal": TITLE,
            "database_unchanged": True,
            "backup_dir": str(backup_dir),
            "changes": [
                "Bỏ dấu vết số phiên bản còn sót trong thông báo sáp nhập phát sinh.",
                "Đổi TARGET/SOURCE thành ĐÍCH/NGUỒN trên bảng kiểm tra nguồn.",
                "Đổi PASS/BLOCK thành ĐẠT/CHẶN trên giao diện.",
                "Đổi từ blocker thành lỗi cần xử lý.",
                "Việt hóa một số thuật ngữ kỹ thuật ở phần xem trước/kết quả phát sinh.",
                "Không thay đổi logic kiểm tra nguồn, mô phỏng, backup, transaction hay ghi database.",
            ],
            "files": {rel: {"sha256": FINAL_HASHES[rel]} for rel in EMBEDDED_FILES},
        }
        report_path.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")

        print()
        print("=" * 104)
        print("CHUẨN HÓA XEM TRƯỚC SÁP NHẬP PHÁT SINH - CÀI ĐẶT THÀNH CÔNG")
        print("Database: KHÔNG THAY ĐỔI")
        print("Đã bỏ dấu vết số phiên bản còn sót trên UI phát sinh.")
        print("TARGET/SOURCE -> ĐÍCH/NGUỒN; PASS/BLOCK -> ĐẠT/CHẶN.")
        print("blocker -> lỗi cần xử lý.")
        print("Logic sáp nhập: GIỮ NGUYÊN.")
        print(f"Backup mã nguồn: {backup_dir}")
        print(f"Báo cáo: {report_path}")
        print("=" * 104)

    except Exception as e:
        try:
            for rel in touched:
                bp = backup_dir / rel
                if bp.exists():
                    p = root / rel
                    p.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(bp, p)
        except Exception:
            pass
        print()
        print("=" * 104)
        print("DỪNG AN TOÀN - CHUẨN HÓA XEM TRƯỚC SÁP NHẬP PHÁT SINH")
        print("Mã nguồn đã được khôi phục nếu đã chạm file.")
        print(f"Lỗi: {e}")
        print("Bộ cài KHÔNG thực hiện sáp nhập và KHÔNG chủ động ghi phocap.db.")
        print("=" * 104)
        if os.environ.get("PHOCAP_INSTALLER_DEBUG") == "1":
            traceback.print_exc()
        raise SystemExit(1)

if __name__ == "__main__":
    main()
